\begin{document}
\begin{tikzpicture}[x=0.009963cm, y=-0.009963cm, line join=round, line width=1.1pt,
  every node/.style={font=\fontsize{11.5}{13.8}\selectfont}]

% Vertices (pixel coordinates)
\coordinate (A) at (105,576);
\coordinate (B) at (814,576);
\coordinate (C) at (814,222);
\coordinate (D) at (105,222);
\coordinate (E) at (548,98);
\coordinate (N) at (370,222);
\coordinate (F) at (725,434);
\coordinate (O) at (381.33,144.64);

% Rectangle ABCD
\draw (A) -- (B) -- (C) -- (D) -- cycle;

% Solid segments E-C, E-N, E-F line and F-(776,313)
\draw (E) -- (C);
\draw (E) -- (N);
\draw (548,99) -- (724,431);
\draw (776,313) -- (726,432);

% Dashed segments
\draw[dashed] (99,224) -- (363,150);
\draw[dashed] (559,95) -- (339,156);
\draw[dashed] (99,578) -- (487,489);
\draw[dashed] (735,432) -- (458,495);

% Partial circular arc, angles 10 to 102 degrees
\draw ($(O)+(10:432.41)$) arc[start angle=10, end angle=102, radius=432.41];

% Labels just outside each vertex
\node[below left] at (A) {$A$};
\node[below right] at (B) {$B$};
\node[above right] at (C) {$C$};
\node[above left] at (D) {$D$};
\node[above] at (E) {$E$};
\node[above left] at (N) {$N$};

\end{tikzpicture}
\end{document}

